import assert from "node:assert/strict";
import { readFile, writeFile } from "node:fs/promises";
import path from "node:path";

import { format } from "oxfmt";

import formatOptions from "../../../oxfmt.config";
import { isTruthy } from "../src/utils/truthy";

const upstream = path.resolve(
  process.argv[2] ??
    path.resolve(
      import.meta.dir,
      "../../../../react-spectrum/packages/react-aria"
    )
);

const upstreamIndex = path.join(upstream, "exports/index.ts");
const content = await readFile(upstreamIndex, "utf-8");

const exports: string[] = [
  "// Generated by scripts/generate-public-barrel.ts.\n",
];

function filename(name: string): string {
  return name
    .replace(/^use/u, "create")
    .replaceAll(/(?<prefix>[A-Z]+)(?<word>[A-Z][a-z])/gu, "$<prefix>-$<word>")
    .replaceAll(
      /(?<prefix>[a-z0-9])(?<capital>[A-Z])/gu,
      "$<prefix>-$<capital>"
    )
    .toLowerCase();
}

const statements = [
  ...content.matchAll(
    /export\s+(?<typeOnly>type\s+)?\{(?<exports>[^}]+)\}\s+from\s+['"](?<module>[^'"]+)['"]/gu
  ),
];

const declarations = await Promise.all(
  statements
    .values()
    .filter(
      (statement) =>
        statement[3]?.includes("useObjectRef") !== true &&
        statement[3]?.includes("mergeRefs") !== true &&
        statement[3]?.includes("SSRProvider") !== true
    )
    .map(async (statement) => {
      const [, typeOnly, exportedNames, moduleSpecifier] = statement;

      if (!isTruthy(exportedNames) || !isTruthy(moduleSpecifier)) {
        throw new Error("Invalid upstream export declaration");
      }

      let module = moduleSpecifier;

      if (module.startsWith("../src/")) {
        const relative = module.slice("../src/".length);
        module = `./${path.dirname(relative)}/${filename(path.basename(relative))}`;
      } else if (module === "@react-types/shared") {
        module = "@solid2-aria/types-shared";
      } else if (module.startsWith("react-stately/")) {
        const stateExport = path.resolve(
          upstream,
          "../react-stately/exports",
          `${module.slice("react-stately/".length)}.ts`
        );

        const stateContent = await readFile(stateExport, "utf-8");
        const name = exportedNames.split(",")[0]?.trim();

        const stateDeclaration = [
          ...stateContent.matchAll(
            /export\s+(?:type\s+)?\{(?<exports>[^}]+)\}\s+from\s+['"]\.\.\/src\/(?<module>[^'"]+)['"]/gu
          ),
        ].find((declaration) =>
          isTruthy(
            declaration[1]?.split(",").some((item) => item.trim() === name)
          )
        );

        const statePath = stateDeclaration?.[2];

        if (!isTruthy(statePath)) {
          throw new Error(`Cannot resolve ${module}`);
        }

        module = `@solid2-aria/stately/${path.dirname(statePath)}/${filename(path.basename(statePath))}`;
      } else if (!module.startsWith("@internationalized/")) {
        throw new Error(`Unexpected public re-export: ${module}`);
      }

      const names = exportedNames
        .split(",")
        .map((name) => {
          const trimmed = name.trim();

          return module === "./focus/focus-scope" &&
            trimmed === "useFocusManager"
            ? "createFocusScopeManager as createFocusManager"
            : trimmed.replaceAll(/\buse(?=[A-Z])/gu, "create");
        })
        .filter(Boolean);

      return `export ${isTruthy(typeOnly) ? "type " : ""}{ ${names.join(", ")} } from ${JSON.stringify(module)};`;
    })
);

exports.push(...declarations);

const destination = path.resolve(import.meta.dir, "../src/index.ts");

const formatted = await format(
  destination,
  `${exports.join("\n\n")}\n`,
  formatOptions
);

assert.equal(
  formatted.errors.length,
  0,
  "Generated exports must be valid TypeScript"
);

await writeFile(destination, formatted.code);
